class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        if (grid.empty()) return 0;
        int m = grid.size();
        int n = grid[0].size();
        int islands = 0;
        const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
        queue<pair<int,int>> q;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == '1') {
                    ++islands;
                    grid[i][j] = '0';
                    q.emplace(i, j);
                    while (!q.empty()) {
                        auto [x, y] = q.front(); q.pop();
                        for (auto &d : dirs) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == '1') {
                                grid[nx][ny] = '0';
                                q.emplace(nx, ny);
                            }
                        }
                    }
                }
            }
        }
        return islands;
    }
};
